0	#!/usr/bin/env node
1	/**
2	 * stage0-post-audit.cjs — Consolidated Stage0 Audit Hook
3	 *
4	 * Merges 8 individual stage0 hooks into one file. Reads stdin ONCE.
5	 * Auto-routes by payload shape:
6	 *   - Has tool_name → PreToolUse → cashflow audit (audit 8)
7	 *   - No tool_name  → Stop hook  → audits 1-7
8	 *
9	 * Stop exit codes: 0 = pass, 2 = BLOCK (first failure wins)
10	 * PreToolUse output: JSON { decision: 'approve'|'block'|'allow', reason? }
11	 */
12	
13	'use strict';
14	
15	const fs = require('fs');
16	const path = require('path');
17	const os = require('os');
18	const { spawnSync } = require('child_process');
19	
20	let isHookEnabled;
21	try { ({ isHookEnabled } = require('./lib/ck-config-utils.cjs')); }
22	catch { isHookEnabled = () => true; }
23	
24	if (!isHookEnabled('stage0-post-audit')) process.exit(0);
25	
26	// Read stdin ONCE — shared by all audits
27	let payload = {};
28	try {
29	  const raw = fs.readFileSync(0, 'utf-8').trim();
30	  if (raw) payload = JSON.parse(raw);
31	} catch { process.exit(0); }
32	
33	if (typeof payload.tool_name === 'string') runCashflowAudit(payload);
34	else runStopAudits(payload);
35	
36	// ── Shared helpers ─────────────────────────────────────────────────────────────
37	
38	function getLastAssistantText(p) {
39	  if (p.transcript_path && fs.existsSync(p.transcript_path)) {
40	    try {
41	      const lines = fs.readFileSync(p.transcript_path, 'utf8').trim().split('\n');
42	      for (let i = lines.length - 1; i >= 0; i--) {
43	        const e = JSON.parse(lines[i]);
44	        if (e.type === 'assistant' || e.role === 'assistant') {
45	          const c = e.content || e.message?.content;
46	          if (typeof c === 'string') return c;
47	          if (Array.isArray(c)) return c.filter(b => b.type === 'text' || !b.type).map(b => b.text || b.content || '').join('\n');
48	        }
49	      }
50	    } catch {}
51	  }
52	  return p.assistant_message || p.message || p.text || '';
53	}
54	
55	function looksLikeVerdict(text) {
56	  if (!text || text.length < 500) return false;
57	  return [/\/stage0 verdict/i, /mountain test v2/i, /brain information flow audit/i, /verdict class/i, /VERDICT:/i]
58	    .filter(r => r.test(text)).length >= 2;
59	}
60	
61	function getRecentIntentClass() {
62	  try {
63	    const tmpDir = os.tmpdir();
64	    const files = fs.readdirSync(tmpDir)
65	      .filter(f => f.startsWith('stage0-intent-class-') && f.endsWith('.json'))
66	      .map(f => ({ name: f, mtime: fs.statSync(path.join(tmpDir, f)).mtimeMs }))
67	      .sort((a, b) => b.mtime - a.mtime);
68	    if (!files.length) return null;
69	    return JSON.parse(fs.readFileSync(path.join(tmpDir, files[0].name), 'utf8')).intent_class || null;
70	  } catch { return null; }
71	}
72	
73	function isStage0ViaTmpFiles() {
74	  try {
75	    const files = fs.readdirSync(os.tmpdir());
76	    return files.some(f => f.startsWith('stage0-intent-class-') || f.startsWith('stage0-runtime-assertions-'));
77	  } catch { return false; }
78	}
