0	#!/usr/bin/env node
1	/**
2	 * SessionStart Hook — Stage0 Learned Rules Injector
3	 *
4	 * Parses .claude/rules/learned-rules.md, extracts P0 (blocking) and P1 (advisory) rules,
5	 * writes structured assertions to /tmp/stage0-runtime-assertions-<session>.json, and
6	 * emits a RUNTIME_ASSERTIONS context block consumed by /stage0 Step 0.5.
7	 *
8	 * Root cause fixed: learned-rules.md was decorative (never parsed at runtime). /stage0
9	 * violated own rules [POWER-LAW-MEDIAN-WARNING] + [FORUM-LAYER-PRIORITY] on 2026-04-13
10	 * platform-rev-share-leakage case because rules were never wired.
11	 *
12	 * Fires: SessionStart (startup, resume, clear, compact)
13	 * Exit: 0 (non-blocking, fail-open)
14	 * Plan ref: plans/260413-1002-stage0-bias-fix/phase-01-foundation-learned-rules-and-classifier.md
15	 */
16	
17	try {
18	  const fs = require('fs');
19	  const path = require('path');
20	  const os = require('os');
21	
22	  // P0 rule tags — BLOCKING at /stage0 decision points. Must fire on every session.
23	  // Missing tags are tolerated (e.g. FORUM-LAYER-PRIORITY not yet in master_investments
24	  // learned-rules.md; will be synced in Phase 2).
25	  const P0_TAGS = new Set([
26	    'CONFABULATION-BAN',
27	    'POWER-LAW-MEDIAN-WARNING',
28	    'FORUM-LAYER-PRIORITY',
29	    'TOOL-EXHAUSTION',
30	    'FAILURE-ARCHAEOLOGY-MANDATORY',
31	    'GMV-INCOME-DIVISION',
32	    'FOUNDER-REALITY-GATE',
33	    'BASE-RATE',
34	    'EVIDENCE-RISK',
35	    'BIG-TECH-CHECK',
36	    'EXECUTION-MINDSET-ENFORCEMENT',
37	    'CONTENT-LAYER-MANDATORY',
38	    'STAGE0-PROFILE-BLOCKING',
39	  ]);
40	
41	  // Check ck.json for hook enable flag (defaults to enabled if flag absent)
42	  function isEnabled() {
43	    try {
44	      const ckJsonPath = path.join(process.cwd(), '.claude', '.ck.json');
45	      if (!fs.existsSync(ckJsonPath)) return true;
46	      const cfg = JSON.parse(fs.readFileSync(ckJsonPath, 'utf8'));
47	      const flag = cfg.hooks && cfg.hooks['stage0-learned-rules-injector'];
48	      return flag !== false; // undefined/true = enabled, false = disabled
49	    } catch {
50	      return true;
51	    }
52	  }
53	
54	  // Parse learned-rules.md lines matching: - [TAG] [DOMAIN] body (source: X, date: Y)
55	  function parseRules(rulesPath) {
56	    if (!fs.existsSync(rulesPath)) {
57	      return { p0: [], p1: [], error: 'file_not_found' };
58	    }
59	    const content = fs.readFileSync(rulesPath, 'utf8');
60	    const lines = content.split('\n');
61	    const p0 = [];
62	    const p1 = [];
63	
64	    // Pattern: bullet + [TAG] + optional [DOMAIN] + body + optional (source: ...)
65	    const re = /^-\s*\[([A-Z][A-Z0-9_-]+)\]\s*(?:\[([A-Z]+)\]\s*)?(.+?)(?:\s*\(source:.*?\))?\s*$/;
66	
67	    for (const raw of lines) {
68	      const line = raw.trim();
69	      const m = line.match(re);
70	      if (!m) continue;
71	      const tag = m[1];
72	      const domain = m[2] || 'ALL';
73	      const body = m[3].trim();
74	      const entry = { tag, domain, body: truncate(body, 300) };
75	      if (P0_TAGS.has(tag)) {
76	        p0.push(entry);
77	      } else {
78	        p1.push(entry);
79	      }
